import numpy as np
from scipy.ndimage import label
def comps_of(a,val):
    m=(a==val); L,n=label(m,structure=np.ones((3,3),bool))
    sizes=[int((L==i).sum()) for i in range(1,n+1)]
    return list(zip(range(1,n+1),sizes))
