                st=[(y,x)]; seen.add((y,x)); comp=[]
                while st:
                    p=st.pop(); comp.append(p)
                    qy,qx=p
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        n=(qy+dy,qx+dx)
                        if 0<=n[0]<H and 0<=n[1]<W and a[n[0]][n[1]]!=bg and n not in seen:
                            seen.add(n); st.append(n)
                comps.append(set(comp))
    return comps

