        for x in range(W):
            if a[y][x]!=0 and lab[y][x]==0:
                q=[(y,x)]; lab[y][x]=ids; cells=[]
                while q:
                    cy,cx=q.pop(); cells.append((cy,cx))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
