# Test: f = for each seed, color it 4; draw from each seed a beam along the perpendicular to its strip (away), until hitting non-bg or strip.
def span(st):
    rs=[p[0] for p in st]; cs=[p[1] for p in st]
    if len(rs)>len(cs): return ('v',min(rs),max(rs),min(cs),max(cs))
    return ('h',min(cs),max(cs),min(rs),max(rs))

def solve(g):
    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                col=g[i][j]; stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in((-1,0),(1,0),(0,-1),(0,1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==col:
                            seen[ny][nx]=True; stack.append((ny,nx))
                comps.append((col,tuple(sorted(cells))))
    out=[r[:] for r in g]
    strips=[c for c in comps if len(c)>1]
    seeds=[c[0] for c in comps if len(c)==1]
    def owns(s_,st):
        o,h_,l_,m_=span(st)
        return (s_[0],s_[1]) if False else (l_<=s_[1]<=m_) if o=='v' else (o<=s_[0]<=h_)
    owned={}
    for s_ in seeds:
        ok=[i for i,st in enumerate(strips) if owns(s_,st)]
        owned[s_]=ok
    # beams from each seed toward... away from nearest strip along perpendicular? use owning strips
    for s_ in seeds:
        sc=g[s_[0]][s_[1]]
        owned_st=strips[owned[s_][0]]
        t,h_,l_,m_=span(owned_st)
        if t=='v':
            step=1 if s_[1]<l_ else -1
            y=s_[0]; x=s_[1]+step
            while 0<y<h and 0<=x<w and g[y][x]==bg:
                out[y][x]=sc; y+=step
        else:
            step=1 if s_[0]<h_ else -1
            y=s_[0]+step; x=s_[1]
            while 0<x<w and 0<=y<h and g[y][x]==bg:
                out[y][x]=sc; y+=step
        out[s_[0]][s_[1]]=4
    return out
